mapper.update:
UPDATE api_credential
SET revoked_at = UTC_TIMESTAMP(6), revoked_by_id = #{revokedById}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND revoked_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM api_credential
WHERE workspace_id = #{workspaceId}
  AND created_by_id = #{userId}
  AND membership_id = #{membershipId}
  AND revoked_at IS NULL
  AND expires_at > UTC_TIMESTAMP(6)

mapper.delete:
DELETE FROM api_credential
WHERE workspace_id = #{workspaceId}
  AND created_by_id = #{userId}
  AND membership_id = #{membershipId}
  AND (revoked_at IS NOT NULL OR expires_at <= UTC_TIMESTAMP(6))

